+      // snapshot에 company_names가 있을 때만 비교 → 구 스냅샷 마이그레이션 시 스푸리어스 트리거 방지
+      const snapshotCompanies = new Set(snapshot.company_names || []);
+      const hasNewCompany = Array.isArray(snapshot.company_names) &&
